mapper.select:
SELECT DISTINCT tradeId,--交易编号 booksetId,--产品代码 booksetName,--产品名称 vDate,--缴税/退税开始日 mDate,--缴税/退税结束日 seitleDate,--缴税/退税日期 interestIncome,--利息收入 dividendIncome,--红利收入 difbetIncome,--价差收入 SUM(interestIncome+dividendIncome+difbetIncome) appreciationTax, --增值税 constructionTax,-- 城建税附加 educationTax,-- 教育税附加 placeeducationTax,-- 地方教育费附加 SUM(constructionTax + educationTax + placeeducationTax) as additionalTax ,-- 增值税附加=城建税+教育费+地方教育费 taxidenType, --缴税/退税 tradeStatus, acctsubjectType, standardCcy FROM (SELECT TPD.TRADE_ID tradeId, BB.BOOKSET_ID booksetId , --产品代码 BB.BOOKSET_NAME booksetName ,--产品名称 to_char(TPD.VDATE, 'yyyy-MM-dd') vDate, --缴税/退税开始日 to_char(TPD.MDATE, 'yyyy-MM-dd') mDate, --缴税/退税结束日 to_char(TPD.SETTLE_DATE, 'yyyy-MM-dd') seitleDate, --缴税/退税日期 NVL( (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{feeType1} ),0) interestIncome, --利息收入 (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{feeType2} )dividendIncome, --红利收入 (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{feeType3} )difbetIncome, --价差收入 (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{feeType4} ) constructionTax,-- 城建税附加 (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{feeType5} ) educationTax,-- 教育税附加 (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE =#{feeType6} )placeeducationTax,-- 地方教育费附加 TPD.PS taxidenType, --缴税/退税 TPD.TRADE_STATUS tradeStatus, --交易方向 BB.ACCT_SUBJECT_TYPE acctsubjectType, BB.STANDARD_CCY standardCcy FROM TRD_PRODUCT_DEAL TPD JOIN BOK_DEAL_ACCOUNTING BDA ON TPD.TRADE_ID = BDA.BUSI_NO AND TPD.BUSI_TYPE = #{busiType} JOIN BOK_BOOKSET BB ON BB.BOOKSET_ID = BDA.BOOKSET_ID WHERE 1 =1
AND BDA.BOOKSET_ID in
#{booksetId }
AND TPD.SETTLE_DATE >=to_date(#{vatDateBegin}, 'yyyy-MM-dd')
AND TPD.SETTLE_DATE <=to_date(#{vatDateEnd}, 'yyyy-MM-dd')
AND TPD.PS=#{taxidenType}
AND TPD.TRADE_ID=#{tradeId}
) GROUP BY tradeId, booksetId, booksetName, vDate, mDate, seitleDate, interestIncome, dividendIncome, difbetIncome, constructionTax, educationTax, placeeducationTax, taxidenType, tradeStatus, acctsubjectType, standardCcy
